-- Add the 56 directory preview profiles to the shared provider tables.
-- Remove the six retired listings by exact ID.
begin;

-- Dependent records for these six IDs follow the existing foreign-key delete rules.
delete from public.providers
where id in (
  'emma-lawson-xe5r',
  'kids-village-orem',
  'les-petits-provo',
  'montessori-learning-center-lindon',
  'way-to-grow-american-fork',
  'guardian-angel-babysitting-utah'
);

create temporary table directory_sample_seed on commit drop as
select value as entry from jsonb_array_elements($directory_seed$
