$directory_seed$::jsonb);

insert into public.languages (name)
select distinct name
from directory_sample_seed
cross join lateral jsonb_array_elements_text(entry->'languages') as lang(name)
on conflict (name) do nothing;

-- Public landmark coordinates from the U.S. Census Geocoder (Public_AR_Current),
-- checked 2026-11-13. These are map references, not fictional facilities.
create temporary table new_directory_samples on commit drop as
with inserted as (
  insert into public.providers (
    id, name, care_type, address, phone, blurb, bio, daily_rate, daily_rate_max,
    listing_origin, is_public, schedule_available, schedule_summary, latitude, longitude
  )
  select p.id, p.name, p.care_type, p.address, p.phone, p.blurb, p.bio, p.daily_rate,
         p.daily_rate_max, 'sample', true, p.schedule_available, p.schedule_summary,
         landmark.latitude, landmark.longitude
  from directory_sample_seed
  cross join lateral jsonb_populate_record(null::public.providers, entry->'listing') p
  join (values
    ('550 N University Ave, Provo, UT 84601', 40.241052, -111.658566),
    ('58 N State St, Orem, UT 84057', 40.298204, -111.695401),
    ('64 S 100 E, American Fork, UT 84003', 40.375441, -111.795967),
    ('30 E Center St, Pleasant Grove, UT 84062', 40.363895, -111.740123),
    ('131 N 100 E, Lehi, UT 84043', 40.389465, -111.847544),
    ('45 S Main St, Springville, UT 84663', 40.166036, -111.610554),
    ('80 S Main St, Spanish Fork, UT 84660', 40.108740, -111.654855)
  ) as landmark(address, latitude, longitude) on landmark.address = p.address
  on conflict (id) do nothing
  returning id
)
select seed.entry, inserted.id
from directory_sample_seed seed
join inserted on inserted.id = seed.entry->'listing'->>'id';

insert into public.provider_pricing_notes (provider_id, note, sort_order)
select sample.id, item.note, item.position - 1
from new_directory_samples sample
cross join lateral jsonb_array_elements_text(entry->'notes') with ordinality as item(note, position);

insert into public.provider_credentials (provider_id, name, verified)
select sample.id, item.name, false
from new_directory_samples sample
cross join lateral jsonb_array_elements_text(entry->'credentials') as item(name);

insert into public.provider_languages (provider_id, language_id)
select sample.id, language.id
from new_directory_samples sample
cross join lateral jsonb_array_elements_text(entry->'languages') as item(name)
join public.languages language on language.name = item.name;

insert into public.provider_availability (provider_id, day_of_week, block)
select sample.id, item.day_of_week, item.block
from new_directory_samples sample
cross join lateral jsonb_to_recordset(entry->'availability')
  as item(day_of_week smallint, block public.time_block);

-- Keep fictional listings out of live recommendations and contact suggestions.
-- provider_match_features() reads this view; directory profiles read providers directly.
create or replace view public.provider_summary with (security_invoker = true) as
select p.id, p.owner_id, p.name, p.care_type, p.blurb, p.bio,
       p.daily_rate, p.daily_rate_max, p.address, p.phone, p.distance_miles,
       p.latitude, p.longitude, p.verified, p.schedule_available,
       p.schedule_summary, p.photo_key, p.created_at,
       round(avg((r.score_experience + r.score_values + r.score_communication + r.score_safety) / 4.0), 1) as rating,
       count(r.id)::int as review_count
from public.providers p
left join public.reviews r on r.provider_id = p.id
where p.listing_origin <> 'sample'
group by p.id;

commit;
